package com.androidhit.lumadrift.wallet;
import android.content.*;import com.androidhit.lumadrift.commerce.*;import com.androidhit.lumadrift.data.SessionEnergyStore;
import java.nio.file.*;import java.util.*;import org.json.JSONObject;
/** Actual controller/journal/energy store, inherited native wallet fixture and explicit disk/HTTP adapters. */
public final class EnergyRefusalV124Test {
 static int checks,coldCases,refusalFaults;static synchronized void ck(boolean b,String why){checks++;if(!b)throw new AssertionError(why);}
 static class Prefs implements SharedPreferences{
  final Map<String,Object> memory=new HashMap<>(),disk=new HashMap<>();boolean fail,memoryFirst;
  public Map<String,?>getAll(){return new HashMap<>(memory);}public boolean contains(String k){return memory.containsKey(k);}public int getInt(String k,int d){return (Integer)memory.getOrDefault(k,d);}public String getString(String k,String d){return(String)memory.getOrDefault(k,d);}public boolean getBoolean(String k,boolean d){return(Boolean)memory.getOrDefault(k,d);}
  public Editor edit(){return new Editor(){final Map<String,Object>w=new HashMap<>();public Editor putInt(String k,int v){w.put(k,v);return this;}public Editor putString(String k,String v){w.put(k,v);return this;}public Editor putBoolean(String k,boolean v){w.put(k,v);return this;}public boolean commit(){if(fail){fail=false;if(memoryFirst)memory.putAll(w);return false;}memory.putAll(w);disk.putAll(w);return true;}};}
  Prefs cold(){var p=new Prefs();p.memory.putAll(disk);p.disk.putAll(disk);return p;}
 }
 static class Ctx extends Context{
  final Map<String,Prefs>files=new HashMap<>();public SharedPreferences getSharedPreferences(String n,int m){return files.computeIfAbsent(n,k->new Prefs());}Prefs wallet(){return(Prefs)getSharedPreferences("luma_energy_purchases_v120",0);}Prefs energy(){return(Prefs)getSharedPreferences("actual_energy",0);}Ctx cold(){coldCases++;var c=new Ctx();files.forEach((k,p)->c.files.put(k,p.cold()));return c;}
 }
 static class Events implements EnergyPurchaseController.Listener{List<String>errors=Collections.synchronizedList(new ArrayList<>());public void onChanged(){}public void onError(String k){errors.add(k);}}
 static Ctx inherited;static String originalSpend,originalUse;
 static void reset(){ProductionWalletClient.created.clear();ProductionWalletClient.currentUid="";ProductionWalletClient.configured=true;CommerceConfig.ready=true;CommerceConfig.MODE_SANDBOX=true;}
 static EnergyPurchaseController lab(Ctx c,Events e){return new EnergyPurchaseController(c,new SessionEnergyStore(c.energy()),e,true,false);}
 static EnergyPurchaseJournal journal(Ctx c){return new EnergyPurchaseJournal(c.wallet());}
 static Ctx inherited(){Ctx c=new Ctx();c.wallet().memory.putAll(inherited.wallet().disk);c.wallet().disk.putAll(inherited.wallet().disk);return c;}
 static String run(int n){return String.format(Locale.ROOT,"00000000-0000-0000-0000-%012d",n);}
 static void energy(Ctx c,int count){var e=new SessionEnergyStore(c.energy());long now=System.currentTimeMillis(),past=now-count*SessionEnergyStore.REFILL_MS;ck(e.snapshot(past).count==10,"actual fresh energy");for(int n=0;n<10;n++){ck(e.reserve(run(n+1),past),"real energy debit");e.confirm(run(n+1),past);}ck(e.snapshot(now).count==count,"real ten-minute regeneration produces requested energy count");}
 static void spendRemaining(Ctx c){var e=new SessionEnergyStore(c.energy());long now=System.currentTimeMillis();int n=0;while(e.snapshot(now).count>0){String id=run(100+n++);ck(e.reserve(id,now),"actual reserve pending refill");e.confirm(id,now);}}
 static void inheritedForeground(){
  reset();Ctx c=inherited();energy(c,4);var events=new Events();var ctl=lab(c,events);ctl.onForeground();var state=journal(c).state(EnergyPurchaseJournal.LAB_UID);
  System.out.println("Inherited0Gold/4energy foreground: statusFR="+ctl.statusLabel("fr")+";phase="+state.phase+";errors="+events.errors);
  ck(ctl.statusLabel("fr").contains("insuffisants")&&!events.errors.contains("commerce_save_error"),"definitive Lab refusal must not become generic save/pending error");
  ck(state.phase.equals("REFUSED")&&!state.pending()&&state.spendId.equals(originalSpend)&&state.useId.equals(originalUse),"durable terminal refusal keeps exact inherited UUIDs");
  ck(ctl.testGoldBalance()==0&&ctl.ownedRefills()==0&&new SessionEnergyStore(c.energy()).snapshot(System.currentTimeMillis()).count==4,"refusal neither debits nor grants/truncates regenerated energy");
  for(String language:List.of("fr","en","de","es","it","pt"))ck(!ctl.statusLabel(language).contains("pending")&&!ctl.statusLabel(language).isBlank(),"readable definitive refusal "+language);
  for(int n=0;n<20;n++)ctl.onForeground();ck(journal(c).state(EnergyPurchaseJournal.LAB_UID).same(state),"foreground retries do not create new request");ctl.close();
  c=c.cold();ctl=lab(c,new Events());ctl.onForeground();ck(ctl.statusLabel("en").startsWith("Not enough LumaGold")&&journal(c).state(EnergyPurchaseJournal.LAB_UID).same(state),"cold recreation retains exact refusal and clear status");ck(ProductionWalletClient.created.isEmpty(),"Lab never initializes network wallet");ctl.close();
 }
 static void failures(){for(boolean memory:new boolean[]{false,true})for(boolean cold:new boolean[]{false,true})for(int n=0;n<100;n++){
  reset();Ctx c=inherited();energy(c,4);c.wallet().memoryFirst=memory;c.wallet().fail=true;var events=new Events();var ctl=lab(c,events);ctl.onForeground();ck(events.errors.contains("commerce_save_error"),"failed refusal commit remains a visible storage failure");ctl.close();if(cold)c=c.cold();ctl=lab(c,new Events());ctl.onForeground();var s=journal(c).state(EnergyPurchaseJournal.LAB_UID);ck(s.phase.equals("REFUSED")&&s.spendId.equals(originalSpend)&&ctl.testGoldBalance()==0&&ctl.ownedRefills()==0,"same/cold-process retry terminalizes only original unpaid Lab intent");ck(new SessionEnergyStore(c.energy()).snapshot(System.currentTimeMillis()).count==4,"refusal recovery preserves regenerated energy");ctl.close();refusalFaults++;
 }}
 static void paidBeforeCrash(){reset();Ctx c=new Ctx();energy(c,4);var j=journal(c);j.seedLab();j.snapshot(EnergyPurchaseJournal.LAB_UID,0,50,1);var s=j.start(EnergyPurchaseJournal.LAB_UID,true);j.labSpend(s);ck(j.balance(EnergyPurchaseJournal.LAB_UID)==0&&j.stock(EnergyPurchaseJournal.LAB_UID)==1,"actual prior atomic payment reaches zeroGold with one owed pack");c=c.cold();var events=new Events();var ctl=lab(c,events);ctl.onForeground();ck(journal(c).state(EnergyPurchaseJournal.LAB_UID).phase.equals("USE")&&ctl.ownedRefills()==1&&!events.errors.contains("wallet_insufficient"),"already-paid SPEND at zeroGold recovers USE instead of being refused");spendRemaining(c);ctl.useStoredRefill();var e=new SessionEnergyStore(c.energy());ck(e.snapshot(System.currentTimeMillis()).count==10&&ctl.ownedRefills()==0&&ctl.testGoldBalance()==0,"actual stored paid pack credits all ten after energy reaches zero");for(int n=0;n<20;n++)ctl.onForeground();ck(e.snapshot(System.currentTimeMillis()).count==10&&journal(c).state(EnergyPurchaseJournal.LAB_UID).phase.equals("EMPTY"),"paid receipt ack cannot double credit");ctl.close();}
 static void explicitRetryAndConcurrency()throws Exception{
  reset();Ctx c=inherited();energy(c,0);var ctl=lab(c,new Events());ctl.onForeground();var old=journal(c).state(EnergyPurchaseJournal.LAB_UID);ctl.buyRefill();var next=journal(c).state(EnergyPurchaseJournal.LAB_UID);ck(next.phase.equals("REFUSED")&&!next.spendId.equals(old.spendId)&&ctl.testGoldBalance()==0,"only explicit new confirmation creates a new refused request; no debit");ctl.close();
  reset();final Ctx shared=inherited();energy(shared,4);List<Throwable>errs=Collections.synchronizedList(new ArrayList<>());List<Thread>threads=new ArrayList<>();for(int n=0;n<32;n++){var t=new Thread(()->{try{var h=lab(shared,new Events());h.onForeground();ck(!h.isBusy()&&h.testGoldBalance()==0,"parallel local refusal is nonbusy and preservesGold");h.close();}catch(Throwable e){errs.add(e);}});threads.add(t);t.start();}for(var t:threads){t.join(5000);ck(!t.isAlive(),"parallel refusal terminates");}ck(errs.isEmpty()&&journal(shared).state(EnergyPurchaseJournal.LAB_UID).spendId.equals(originalSpend),"32handles preserve one terminal request");
  reset();final Ctx paid=new Ctx();energy(paid,0);var j=journal(paid);j.seedLab();j.snapshot(EnergyPurchaseJournal.LAB_UID,0,50,1);var intended=j.start(EnergyPurchaseJournal.LAB_UID,true);errs.clear();threads.clear();var events=new Events();
  for(int n=0;n<32;n++){var t=new Thread(()->{try{var h=lab(paid,events);h.onForeground();h.close();}catch(Throwable e){errs.add(e);}});threads.add(t);t.start();}for(var t:threads){t.join(5000);ck(!t.isAlive(),"parallel paid recovery terminates");}
  String hash=EnergyPurchaseJournal.receiptHash(EnergyPurchaseJournal.LAB_UID,intended.useId);ck(errs.isEmpty()&&!events.errors.contains("wallet_insufficient")&&j.balance(EnergyPurchaseJournal.LAB_UID)==0&&j.stock(EnergyPurchaseJournal.LAB_UID)==0&&new SessionEnergyStore(paid.energy()).hasReceipt(hash)&&new SessionEnergyStore(paid.energy()).snapshot(System.currentTimeMillis()).count==10,"32paid handles debit exactly50 once and credit the same pack once; zero balance after payment is never a refusal");
 }
 static void networkAmbiguity(){reset();Ctx c=new Ctx();energy(c,0);ProductionWalletClient.currentUid="google-A";var e=new SessionEnergyStore(c.energy());var ctl=new EnergyPurchaseController(c,e,new Events(),false,true);ctl.buyRefill();var w=ProductionWalletClient.created.get(0);var spend=w.spends.get(0);spend.callback.onError("wallet_insufficient");var state=journal(c).state("google-A");ck(state.phase.equals("SPEND")&&state.spendId.equals(spend.id),"network insufficient error is never automatically terminalized by Lab policy");spend.callback.onError("wallet_unavailable");ctl.close();var next=new EnergyPurchaseController(c,e,new Events(),false,true);next.onForeground();var retry=ProductionWalletClient.created.get(ProductionWalletClient.created.size()-1);ck(retry.spends.get(0).id.equals(spend.id)&&e.snapshot(System.currentTimeMillis()).count==0,"network retry reuses same UUID and grants nothing on ambiguous error");next.close();}
 public static void main(String[]args)throws Exception{
  inherited=new Ctx();journal(inherited).seedLab(); // Native observer intentionally omits every key containing 'seed'. Initialize via the real API before overlaying its disclosed wallet fields.
  var fixture=new JSONObject(Files.readString(Path.of(args[0])));for(String k:fixture.keySet()){Object v=fixture.get(k);inherited.wallet().memory.put(k,v);inherited.wallet().disk.put(k,v);}var s=journal(inherited).state(EnergyPurchaseJournal.LAB_UID);originalSpend=s.spendId;originalUse=s.useId;ck(s.phase.equals("SPEND")&&journal(inherited).balance(EnergyPurchaseJournal.LAB_UID)==0&&journal(inherited).stock(EnergyPurchaseJournal.LAB_UID)==0,"exact inherited native fixture bound");
  inheritedForeground();failures();paidBeforeCrash();explicitRetryAndConcurrency();networkAmbiguity();String report="{\"status\":\"PASS\",\"assertions\":"+checks+",\"refusalWriteFailureCases\":"+refusalFaults+",\"coldReconstructions\":"+coldCases+",\"concurrentHandles\":32,\"scope\":\"Actual controller/journal/SessionEnergyStore with inherited native Lab wallet fixture, disk and HTTP callback doubles. No new APK/native/provider qualification.\"}\n";Files.writeString(Path.of(args[1]),report);System.out.print(report);
 }
}
